--
-- Name: vw_admission_year_overview; Type: VIEW; Schema: admissions_dw; Owner: -
--

CREATE VIEW admissions_dw.vw_admission_year_overview AS
 SELECT y.academic_year,
    count(*) AS application_choices,
    count(DISTINCT f.student_key) AS unique_applicants,
    count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)) AS confirmed_unique_applicants,
    round(((count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)))::numeric / (NULLIF(count(DISTINCT f.student_key), 0))::numeric), 4) AS confirmed_unique_rate,
    count(DISTINCT f.major_key) AS unique_majors,
    count(DISTINCT f.round_key) AS tcas_rounds,
    count(DISTINCT f.source_file) AS source_files,
    round(avg(f.score), 4) AS avg_score,
    count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = ANY (ARRAY['สละสิทธิ์'::text, 'สละสิทธิ์ในรอบ 2'::text]))) AS resigned_unique_applicants,
    count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = ANY (ARRAY['ยืนยันสิทธิ์'::text, 'สละสิทธิ์'::text, 'สละสิทธิ์ในรอบ 2'::text, 'ยืนยันที่อื่นแล้ว'::text, 'ไม่ใช้สิทธิ์'::text, 'ผ่านการคัดเลือก'::text, 'ผ่านการคัดเลือกแต่ไม่นำมาประมวลผลรอบที่ 2'::text, 'ไม่เข้าระบบมาดำเนินการใดๆ'::text]))) AS eligible_unique_applicants
   FROM ((admissions_dw.fact_admission f
     JOIN admissions_dw.dim_year y ON ((y.year_key = f.year_key)))
     JOIN admissions_dw.dim_tcas_status s ON ((s.status_key = f.status_key)))
  GROUP BY y.academic_year;


--
-- Name: mart_admissions_executive_summary; Type: VIEW; Schema: admissions_dw; Owner: -
--

CREATE VIEW admissions_dw.mart_admissions_executive_summary AS
 SELECT academic_year,
    application_choices,
    unique_applicants,
    confirmed_unique_applicants AS confirmed_applicants,
    round((confirmed_unique_rate * (100)::numeric), 2) AS confirmed_rate,
    source_files,
    avg_score,
    unique_majors,
    tcas_rounds,
    (unique_applicants - lag(unique_applicants) OVER (ORDER BY academic_year)) AS applicant_change,
    (confirmed_unique_applicants - lag(confirmed_unique_applicants) OVER (ORDER BY academic_year)) AS confirmed_change,
    resigned_unique_applicants AS resigned_applicants,
    eligible_unique_applicants AS eligible_applicants
   FROM admissions_dw.vw_admission_year_overview;


--
-- Name: mart_admissions_year_change; Type: VIEW; Schema: admissions_dw; Owner: -
--

CREATE VIEW admissions_dw.mart_admissions_year_change AS
 SELECT academic_year,
    application_choices,
    unique_applicants,
    confirmed_applicants,
    confirmed_rate,
    source_files,
    avg_score,
    unique_majors,
    tcas_rounds,
    applicant_change,
    confirmed_change,
    resigned_applicants,
    eligible_applicants,
    (unique_applicants - lag(unique_applicants) OVER (ORDER BY academic_year)) AS applicant_delta,
    (confirmed_applicants - lag(confirmed_applicants) OVER (ORDER BY academic_year)) AS confirmed_delta,
    (confirmed_rate - lag(confirmed_rate) OVER (ORDER BY academic_year)) AS rate_delta
   FROM admissions_dw.mart_admissions_executive_summary;


--
-- Name: mart_major_conversion; Type: VIEW; Schema: admissions_dw; Owner: -
--

CREATE VIEW admissions_dw.mart_major_conversion AS
 WITH major_year AS (
         SELECT y.academic_year,
            m.major_key,
            m.major_id AS major_code,
            m.major_name,
            m.major_type AS program_type,
            count(DISTINCT f.student_key) AS applicant_count,
            count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)) AS confirmed_count,
            round((((count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)))::numeric * (100)::numeric) / (NULLIF(count(DISTINCT f.student_key), 0))::numeric), 2) AS confirmed_rate,
            round(avg(f.score), 4) AS avg_score,
            count(*) AS application_choices,
            count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = ANY (ARRAY['ยืนยันสิทธิ์'::text, 'สละสิทธิ์'::text, 'สละสิทธิ์ในรอบ 2'::text, 'ยืนยันที่อื่นแล้ว'::text, 'ไม่ใช้สิทธิ์'::text, 'ผ่านการคัดเลือก'::text, 'ผ่านการคัดเลือกแต่ไม่นำมาประมวลผลรอบที่ 2'::text, 'ไม่เข้าระบบมาดำเนินการใดๆ'::text]))) AS eligible_count
           FROM (((admissions_dw.fact_admission f
             JOIN admissions_dw.dim_year y ON ((y.year_key = f.year_key)))
             JOIN admissions_dw.dim_major m ON ((m.major_key = f.major_key)))
             JOIN admissions_dw.dim_tcas_status s ON ((s.status_key = f.status_key)))
          GROUP BY m.major_key, y.academic_year, m.major_id, m.major_name, m.major_type
        )
 SELECT academic_year,
    major_code,
    major_name,
    program_type,
    applicant_count,
    confirmed_count,
    confirmed_rate,
    avg_score,
    COALESCE((applicant_count - lag(applicant_count) OVER (PARTITION BY major_key ORDER BY academic_year)), (0)::bigint) AS applicant_change,
    COALESCE((confirmed_count - lag(confirmed_count) OVER (PARTITION BY major_key ORDER BY academic_year)), (0)::bigint) AS confirmed_change,
    rank() OVER (PARTITION BY academic_year ORDER BY applicant_count DESC) AS demand_rank,
    application_choices,
    eligible_count,
    major_key
   FROM major_year;


