--
-- Name: vw_admission_round_overview; Type: VIEW; Schema: admissions_dw; Owner: -
--

CREATE VIEW admissions_dw.vw_admission_round_overview AS
 SELECT y.academic_year,
    r.tcas_round_code,
    r.tcas_round_name,
    count(*) AS choices,
    count(DISTINCT f.student_key) AS unique_applicants,
    count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)) AS confirmed_applicants,
    round((((count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = 'ยืนยันสิทธิ์'::text)))::numeric * (100)::numeric) / (NULLIF(count(DISTINCT f.student_key), 0))::numeric), 2) AS confirmed_rate,
    count(DISTINCT f.source_file) AS source_files,
    round(avg(f.score), 4) AS avg_score,
    count(DISTINCT f.student_key) FILTER (WHERE (s.tcas_status = ANY (ARRAY['ยืนยันสิทธิ์'::text, 'สละสิทธิ์'::text, 'สละสิทธิ์ในรอบ 2'::text, 'ยืนยันที่อื่นแล้ว'::text, 'ไม่ใช้สิทธิ์'::text, 'ผ่านการคัดเลือก'::text, 'ผ่านการคัดเลือกแต่ไม่นำมาประมวลผลรอบที่ 2'::text, 'ไม่เข้าระบบมาดำเนินการใดๆ'::text]))) AS eligible_applicants
   FROM (((admissions_dw.fact_admission f
     JOIN admissions_dw.dim_year y ON ((y.year_key = f.year_key)))
     JOIN admissions_dw.dim_tcas_round r ON ((r.round_key = f.round_key)))
     JOIN admissions_dw.dim_tcas_status s ON ((s.status_key = f.status_key)))
